174	// validateVSCodeEvent checks whether the hookEventName is consistent with the
175	// CLI hook subcommand that was invoked. Returns true if the event should be
176	// processed, false if it should be silently skipped (mismatch or unknown event).
177	func validateVSCodeEvent(env *hookEnvelope, hookName string) bool {
178		hookEventName := env.HookEventName
179		allowedHooks, known := vsCodeEventToHookNames[hookEventName]
180		if !known {
181			return false
182		}
183		if !slices.Contains(allowedHooks, hookName) {
184			return false
185		}
186	
187		// VS Code overloads "Stop" for both end-of-turn and terminal session-stop
188		// payloads. Route them by reason to avoid ending sessions on ordinary turns.
189		if hookEventName == VSCodeEventStop {
190			isTerminal := isTerminalVSCodeStop(env)
191			switch hookName {
192			case HookNameAgentStop:
193				return !isTerminal
194			case HookNameSessionEnd:
195				return isTerminal
196			}
197		}
198	
199		return true
200	}
